const MEMO_ID: Pubkey = pubkey!("MemoSq4gqABAXKb96qnH8TysNcWxMyWCqXgDLGmfcHr");
const TWO64: f64 = 18_446_744_073_709_551_616f64;
const T_WX: u64 = 5;

fn kp(n: u8) -> Keypair {
    Keypair::new_from_array([n; 32])
}
fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}
fn b64(b: &[u8]) -> String {
    base64::engine::general_purpose::STANDARD.encode(b)
}
fn ordered(a: &Pubkey, b: &Pubkey) -> (Pubkey, Pubkey) {
    if a > b {
        (*a, *b)
    } else {
        (*b, *a)
    }
}
fn dbc_pool_q(config: &Pubkey, base: &Pubkey, quote: &Pubkey) -> Pubkey {
    let (hi, lo) = ordered(base, quote);
    pda(&[b"pool", config.as_ref(), hi.as_ref(), lo.as_ref()], &DBC_ID)
}
fn damm_mig_pool(base: &Pubkey, quote: &Pubkey) -> Pubkey {
    let (hi, lo) = ordered(base, quote);
    pda(&[b"pool", DAMM_CONFIG_CUSTOMIZABLE.as_ref(), hi.as_ref(), lo.as_ref()], &DAMM_V2_ID)
}
fn cpool(a: &Pubkey, b: &Pubkey) -> Pubkey {
    let (hi, lo) = ordered(a, b);
    pda(&[b"cpool", hi.as_ref(), lo.as_ref()], &DAMM_V2_ID)
}
fn metadata_pda(mint: &Pubkey) -> Pubkey {
    pda(&[b"metadata", MPL_ID.as_ref(), mint.as_ref()], &MPL_ID)
}
fn memo(text: &str, signers: &[Pubkey]) -> Instruction {
    Instruction { program_id: MEMO_ID, accounts: signers.iter().map(|k| AccountMeta::new_readonly(*k, true)).collect(), data: text.as_bytes().to_vec() }
}
fn borsh_str(v: &mut Vec<u8>, s: &str) {
    v.extend_from_slice(&(s.len() as u32).to_le_bytes());
    v.extend_from_slice(s.as_bytes());
}
/// Token Metadata `CreateMetadataAccountV3` (33), as the spike: no creators, 0 royalty, mutable, update authority named.
fn ix_create_metadata_v3(mint: &Pubkey, mint_authority: &Pubkey, payer: &Pubkey, update_authority: &Pubkey, name: &str, symbol: &str, uri: &str) -> Instruction {
    let mut d = vec![33u8];
    borsh_str(&mut d, name);
    borsh_str(&mut d, symbol);
    borsh_str(&mut d, uri);
    d.extend_from_slice(&0u16.to_le_bytes());
    d.extend_from_slice(&[0, 0, 0]);
    d.push(1);
    d.push(0);
    Instruction {
        program_id: MPL_ID,
        accounts: vec![
            AccountMeta::new(metadata_pda(mint), false),
            AccountMeta::new_readonly(*mint, false),
            AccountMeta::new_readonly(*mint_authority, true),
            AccountMeta::new(*payer, true),
            AccountMeta::new_readonly(*update_authority, false),
            AccountMeta::new_readonly(anchor_lang::system_program::ID, false),
        ],
        data: d,
    }
}
/// Token Metadata `UpdateMetadataAccountV2` (15): new data (name, symbol, uri; no creators/collection/uses), nothing else changed.
fn ix_update_metadata_v2(mint: &Pubkey, update_authority: &Pubkey, name: &str, symbol: &str, uri: &str) -> Instruction {
    let mut d = vec![15u8, 1];
    borsh_str(&mut d, name);
    borsh_str(&mut d, symbol);
    borsh_str(&mut d, uri);
    d.extend_from_slice(&0u16.to_le_bytes());
    d.extend_from_slice(&[0, 0, 0]); // creators, collection, uses: None
    d.extend_from_slice(&[0, 0, 0]); // update_authority, primary_sale_happened, is_mutable: None
    Instruction { program_id: MPL_ID, accounts: vec![AccountMeta::new(metadata_pda(mint), false), AccountMeta::new_readonly(*update_authority, true)], data: d }
}

fn curve_for(t_wx: u64) -> (u128, Vec<(u128, u128)>) {
    let j: Value = serde_json::from_str(
        &std::fs::read_to_string(std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/s1_wx_curves.json")).unwrap(),
    )
    .unwrap();
    let c = &j[t_wx.to_string()];
    let s = c["sqrtStartPrice"].as_str().unwrap().parse().unwrap();
    let curve = c["curve"].as_array().unwrap().iter().map(|p| (p["sqrtPrice"].as_str().unwrap().parse().unwrap(), p["liquidity"].as_str().unwrap().parse().unwrap())).collect();
    (s, curve)
}
fn wx_params(t_wx: u64) -> dbct::ConfigParameters {
    let mut p = rook_config_params(50);
    let (s, curve) = curve_for(t_wx);
    p.migration_quote_threshold = t_wx * LAMPORTS;
    p.sqrt_start_price = s;
    p.curve = curve.iter().map(|(s, l)| dbct::LiquidityDistributionParameters { sqrt_price: *s, liquidity: *l }).collect();
    // the creator's launch buy at the minimum fee (dbc::pins::FIRST_SWAP_WITH_MIN_FEE, operator decision 2026-10-11)
    p.enable_first_swap_with_min_fee = true;
    p
}
fn liquidity_for(a: u64, b: u64, s: u128, smin: u128, smax: u128) -> u128 {
    let sp = s as f64 / TWO64;
    let lo = smin as f64 / TWO64;
    let hi = smax as f64 / TWO64;
    let la = a as f64 / (1.0 / sp - 1.0 / hi);
    let lb = b as f64 / (sp - lo);
    (la.min(lb) * 0.999_999 * TWO64) as u128
}
fn sqrt_of(lamports_per_whole: f64) -> u128 {
    ((lamports_per_whole / 1e9).sqrt() * TWO64) as u128
}

#[derive(Clone, Copy)]
struct Damm {
    pool: Pubkey,
    a: Pubkey,
    b: Pubkey,
}
impl Damm {
    fn va(&self) -> Pubkey {
        damm_vault(&self.a, &self.pool)
    }
    fn vb(&self) -> Pubkey {
        damm_vault(&self.b, &self.pool)
    }
}
fn ix_damm_swap(p: &Damm, trader: &Pubkey, input: Pubkey, output: Pubkey, amount_in: u64, min_out: u64) -> Instruction {
    Instruction {
        program_id: DAMM_V2_ID,
        accounts: cp_amm::client::accounts::Swap {
            pool_authority: DAMM_V2_POOL_AUTHORITY,
            pool: p.pool,
            input_token_account: input,
            output_token_account: output,
            token_a_vault: p.va(),
            token_b_vault: p.vb(),
            token_a_mint: p.a,
            token_b_mint: p.b,
            payer: *trader,
            token_a_program: spl_token::ID,
            token_b_program: spl_token::ID,
            referral_token_account: None,
            event_authority: event_authority(&DAMM_V2_ID),
            program: DAMM_V2_ID,
        }
        .to_account_metas(None),
        data: cp_amm::client::args::Swap { _params: cp_amm::types::SwapParameters { amount_in, minimum_amount_out: min_out } }.data(),
    }
}
fn ix_damm_swap2(p: &Damm, trader: &Pubkey, input: Pubkey, output: Pubkey, amount_0: u64, amount_1: u64, mode: u8) -> Instruction {
    Instruction {
        program_id: DAMM_V2_ID,
        accounts: cp_amm::client::accounts::Swap2 {
            pool_authority: DAMM_V2_POOL_AUTHORITY,
            pool: p.pool,
            input_token_account: input,
            output_token_account: output,
            token_a_vault: p.va(),
            token_b_vault: p.vb(),
            token_a_mint: p.a,
            token_b_mint: p.b,
            payer: *trader,
            token_a_program: spl_token::ID,
            token_b_program: spl_token::ID,
            referral_token_account: None,
            event_authority: event_authority(&DAMM_V2_ID),
            program: DAMM_V2_ID,
        }
        .to_account_metas(None),
        data: cp_amm::client::args::Swap2 { _params: cp_amm::types::SwapParameters2 { amount_0, amount_1, swap_mode: mode } }.data(),
    }
}
fn ix_damm_claim(p: &Damm, nft: &Pubkey, owner: &Pubkey, a_acc: Pubkey, b_acc: Pubkey) -> Instruction {
    Instruction {
        program_id: DAMM_V2_ID,
        accounts: cp_amm::client::accounts::ClaimPositionFee {
            pool_authority: DAMM_V2_POOL_AUTHORITY,
            pool: p.pool,
            position: damm_position(nft),
            token_a_account: a_acc,
            token_b_account: b_acc,
            token_a_vault: p.va(),
            token_b_vault: p.vb(),
            token_a_mint: p.a,
            token_b_mint: p.b,
            position_nft_account: damm_position_nft_account(nft),
            signer: *owner,
            token_a_program: spl_token::ID,
            token_b_program: spl_token::ID,
            event_authority: event_authority(&DAMM_V2_ID),
            program: DAMM_V2_ID,
        }
        .to_account_metas(None),
        data: cp_amm::client::args::ClaimPositionFee {}.data(),
    }
}
fn ix_damm_add(p: &Damm, nft: &Pubkey, owner: &Pubkey, a: Pubkey, b: Pubkey, liq: u128, max_a: u64, max_b: u64) -> Instruction {
    Instruction {
        program_id: DAMM_V2_ID,
        accounts: cp_amm::client::accounts::AddLiquidity {
            pool: p.pool,
            position: damm_position(nft),
            token_a_account: a,
            token_b_account: b,
            token_a_vault: p.va(),
            token_b_vault: p.vb(),
            token_a_mint: p.a,
            token_b_mint: p.b,
            position_nft_account: damm_position_nft_account(nft),
            signer: *owner,
            token_a_program: spl_token::ID,
            token_b_program: spl_token::ID,
            event_authority: event_authority(&DAMM_V2_ID),
            program: DAMM_V2_ID,
        }
        .to_account_metas(None),
        data: cp_amm::client::args::AddLiquidity {
            params: cp_amm::types::AddLiquidityParameters { liquidity_delta: liq, token_a_amount_threshold: max_a, token_b_amount_threshold: max_b },
        }
        .data(),
    }
}
fn remove_accounts(p: &Damm, nft: &Pubkey, owner: &Pubkey, a: Pubkey, b: Pubkey) -> Vec<AccountMeta> {
    cp_amm::client::accounts::RemoveLiquidity {
        pool_authority: DAMM_V2_POOL_AUTHORITY,
        pool: p.pool,
        position: damm_position(nft),
        token_a_account: a,
        token_b_account: b,
        token_a_vault: p.va(),
        token_b_vault: p.vb(),
        token_a_mint: p.a,
        token_b_mint: p.b,
        position_nft_account: damm_position_nft_account(nft),
        signer: *owner,
        token_a_program: spl_token::ID,
        token_b_program: spl_token::ID,
        event_authority: event_authority(&DAMM_V2_ID),
        program: DAMM_V2_ID,
    }
    .to_account_metas(None)
}
fn base_fee(num: u64) -> cp_amm::types::BaseFeeParameters {
    let mut d = [0u8; 27];
    d[..8].copy_from_slice(&num.to_le_bytes());
    cp_amm::types::BaseFeeParameters { data: d }
}

struct Rec {
    ixs: Vec<Value>,
    /// built by the IDL-generated client but not sent (no account to run it against in LiteSVM)
    idl_only: Vec<Value>,
    bundles: Vec<Value>,
    accounts: Vec<Value>,
}
fn jix(name: &str, ix: &Instruction, params: Value) -> Value {
    json!({
        "name": name,
        "program": ix.program_id.to_string(),
        "accounts": ix.accounts.iter().map(|a| json!([a.pubkey.to_string(), a.is_signer, a.is_writable])).collect::<Vec<_>>(),
        "data": hex(&ix.data),
        "params": params,
    })
}
impl Rec {
    fn ix(&mut self, name: &str, ix: &Instruction, params: Value) {
        self.ixs.push(jix(name, ix, params));
    }
    fn account(&mut self, name: &str, env: &Env, key: &Pubkey, expect: Value) {
        let a = env.svm.get_account(key).unwrap();
        self.accounts.push(json!({"name": name, "key": key.to_string(), "owner": a.owner.to_string(), "data": b64(&a.data), "expect": expect}));
    }
}
fn s(k: &Pubkey) -> String {
    k.to_string()
}
fn opt(k: Option<Pubkey>) -> Value {
    k.map(|k| Value::String(k.to_string())).unwrap_or(Value::Null)
}

#[test]
fn solix2_fixtures() {
    let mut env = Env::new();
    // deterministic K_main (fee payer of every transaction)
    env.payer = kp(1);
    env.svm.airdrop(&env.payer.pubkey(), 10_000 * LAMPORTS).unwrap();
    let payer = env.payer.pubkey();
    let hot = kp(2);
    env.svm.airdrop(&hot.pubkey(), LAMPORTS).unwrap();
    let wx_kp = kp(3);
    let wx = wx_kp.pubkey();
    let canister = kp(4); // K_coll[i], here also K_fc as in the spike
    let k = canister.pubkey();
    env.svm.airdrop(&k, LAMPORTS).unwrap();
    let mut r = Rec { ixs: vec![], idl_only: vec![], bundles: vec![], accounts: vec![] };

    // ---- 1. the ceremony (§2): one transaction
    let rent = env.svm.minimum_balance_for_rent_exemption(82);
    let (name, symbol, uri) = ("Wrapped Milady", "wMILADY", "https://rook.example/wx.json");
    let c1 = system_instruction::create_account(&payer, &wx, rent, 82, &spl_token::ID);
    let c2 = spl_token::instruction::initialize_mint2(&spl_token::ID, &wx, &hot.pubkey(), None, 9).unwrap();
    let c3 = ix_create_metadata_v3(&wx, &hot.pubkey(), &payer, &k, name, symbol, uri);
    let c4 = spl_token::instruction::set_authority(&spl_token::ID, &wx, Some(&k), spl_token::instruction::AuthorityType::MintTokens, &hot.pubkey(), &[]).unwrap();
    env.send_ok("ceremony", &[c1.clone(), c2.clone(), c3.clone(), c4.clone()], &[&hot, &wx_kp]);
    r.ix("system.create_account", &c1, json!({"from": s(&payer), "new": s(&wx), "lamports": rent, "space": 82, "owner": s(&spl_token::ID)}));
    r.ix("spl.initialize_mint2", &c2, json!({"mint": s(&wx), "authority": s(&hot.pubkey()), "freeze": null, "decimals": 9}));
    r.ix("mpl.create_metadata_v3", &c3, json!({"mint": s(&wx), "mint_authority": s(&hot.pubkey()), "payer": s(&payer), "update_authority": s(&k), "name": name, "symbol": symbol, "uri": uri}));
    r.ix("spl.set_authority", &c4, json!({"account": s(&wx), "kind": 0, "new": s(&k), "current": s(&hot.pubkey())}));
    let m = spl_token::state::Mint::unpack(&env.raw(&wx)[..82]).unwrap();
    r.account("wx_mint", &env, &wx, json!({"mint_authority": opt(m.mint_authority.into()), "supply": m.supply, "decimals": m.decimals, "is_initialized": m.is_initialized, "freeze_authority": opt(m.freeze_authority.into())}));

    // a second mint WITH a freeze authority, for the canister's refusal (DBC itself accepts it, S1b)
    let frz_kp = kp(30);
    let f1 = system_instruction::create_account(&payer, &frz_kp.pubkey(), rent, 82, &spl_token::ID);
    let f2 = spl_token::instruction::initialize_mint2(&spl_token::ID, &frz_kp.pubkey(), &k, Some(&k), 9).unwrap();
    env.send_ok("freeze mint", &[f1, f2.clone()], &[&frz_kp]);
    r.ix("spl.initialize_mint2", &f2, json!({"mint": s(&frz_kp.pubkey()), "authority": s(&k), "freeze": s(&k), "decimals": 9}));
    let m = spl_token::state::Mint::unpack(&env.raw(&frz_kp.pubkey())[..82]).unwrap();
    r.account("frozen_mint", &env, &frz_kp.pubkey(), json!({"mint_authority": opt(m.mint_authority.into()), "supply": m.supply, "decimals": m.decimals, "is_initialized": m.is_initialized, "freeze_authority": opt(m.freeze_authority.into())}));

    // ---- 2. the canister renames wX (update authority = K_coll)
    let u = ix_update_metadata_v2(&wx, &k, "Wrapped Milady Maker", symbol, "https://rook.example/wx2.json");
    env.send_ok("update metadata", &[u.clone()], &[&canister]);
    r.ix("mpl.update_metadata_v2", &u, json!({"mint": s(&wx), "update_authority": s(&k), "name": "Wrapped Milady Maker", "symbol": symbol, "uri": "https://rook.example/wx2.json"}));

    // ---- 3. the wX/SOL pool (§5, revised): desk ATAs first, then mint seed + wrap + pool, then the memo
    let desk = kp(13);
    env.svm.airdrop(&desk.pubkey(), 50 * LAMPORTS).unwrap();
    let dk = desk.pubkey();
    let desk_wx = get_associated_token_address(&dk, &wx);
    let desk_wsol = get_associated_token_address(&dk, &NATIVE_MINT);
    let a1 = ata_ix::create_associated_token_account_idempotent(&payer, &dk, &wx, &spl_token::ID);
    let a2 = ata_ix::create_associated_token_account_idempotent(&payer, &dk, &NATIVE_MINT, &spl_token::ID);
    env.send_ok("desk atas", &[a1.clone(), a2.clone()], &[]);
    r.ix("ata.create_idempotent", &a1, json!({"payer": s(&payer), "owner": s(&dk), "mint": s(&wx)}));
    r.ix("ata.create_idempotent", &a2, json!({"payer": s(&payer), "owner": s(&dk), "mint": s(&NATIVE_MINT)}));
    let floor = 18.61e9;
    let s0 = sqrt_of(floor);
    let (smin, smax) = ((s0 as f64 / 1.1) as u128, (s0 as f64 * 1.1) as u128); // [p/1.21, 1.21p]
    let seed_sol = 10 * LAMPORTS;
    let seed_wx = (seed_sol as f64 / floor * 1e9) as u64;
    let liq = liquidity_for(seed_wx, seed_sol, s0, smin, smax);
    let nft = kp(14);
    let pool = cpool(&wx, &NATIVE_MINT);
    let wp = Damm { pool, a: wx, b: NATIVE_MINT };
    let params = cp_amm::types::InitializeCustomizablePoolParameters {
        pool_fees: cp_amm::types::PoolFeeParameters { base_fee: base_fee(5_000_000), compounding_fee_bps: 0, padding: 0, dynamic_fee: None },
        sqrt_min_price: smin,
        sqrt_max_price: smax,
        has_alpha_vault: false,
        liquidity: liq,
        sqrt_price: s0,
        activation_type: 1,
        collect_fee_mode: 1,
        activation_point: None,
    };
    let init = Instruction {
        program_id: DAMM_V2_ID,
        accounts: cp_amm::client::accounts::InitializeCustomizablePool {
            creator: dk,
            position_nft_mint: nft.pubkey(),
            position_nft_account: damm_position_nft_account(&nft.pubkey()),
            payer: dk,
            pool_authority: DAMM_V2_POOL_AUTHORITY,
            pool,
            position: damm_position(&nft.pubkey()),
            token_a_mint: wx,
            token_b_mint: NATIVE_MINT,
            token_a_vault: wp.va(),
            token_b_vault: wp.vb(),
            payer_token_a: desk_wx,
            payer_token_b: desk_wsol,
            token_a_program: spl_token::ID,
            token_b_program: spl_token::ID,
            token_2022_program: TOKEN_2022_ID,
            system_program: anchor_lang::system_program::ID,
            event_authority: event_authority(&DAMM_V2_ID),
            program: DAMM_V2_ID,
        }
        .to_account_metas(None),
        data: cp_amm::client::args::InitializeCustomizablePool { params }.data(),
    };
    let mt = spl_token::instruction::mint_to_checked(&spl_token::ID, &wx, &desk_wx, &k, &[], seed_wx, 9).unwrap();
    let tr = system_instruction::transfer(&dk, &desk_wsol, seed_sol);
    let sn = spl_token::instruction::sync_native(&spl_token::ID, &desk_wsol).unwrap();
    env.send_ok("open pool", &[mt.clone(), tr.clone(), sn.clone(), init.clone()], &[&canister, &desk, &nft]);
    r.ix("spl.mint_to_checked", &mt, json!({"mint": s(&wx), "dest": s(&desk_wx), "authority": s(&k), "amount": seed_wx, "decimals": 9}));
    r.ix("system.transfer", &tr, json!({"from": s(&dk), "to": s(&desk_wsol), "lamports": seed_sol}));
    r.ix("spl.sync_native", &sn, json!({"account": s(&desk_wsol)}));
    r.ix("damm.initialize_customizable_pool", &init, json!({
        "creator": s(&dk), "payer": s(&dk), "nft_mint": s(&nft.pubkey()), "token_a_mint": s(&wx), "token_b_mint": s(&NATIVE_MINT),
        "payer_token_a": s(&desk_wx), "payer_token_b": s(&desk_wsol), "fee_numerator": 5_000_000u64, "sqrt_min_price": smin.to_string(),
        "sqrt_max_price": smax.to_string(), "liquidity": liq.to_string(), "sqrt_price": s0.to_string(), "activation_type": 1, "collect_fee_mode": 1
    }));
    let me = memo("rook:v1:0:pool:open", &[k]);
    env.send_ok("memo", &[me.clone()], &[&canister]);
    r.ix("memo", &me, json!({"text": "rook:v1:0:pool:open", "signers": [s(&k)]}));
    r.account("wx_sol_pool", &env, &pool, json!({"token_a_mint": s(&wx), "token_b_mint": s(&NATIVE_MINT), "token_a_vault": s(&wp.va()), "token_b_vault": s(&wp.vb()),
        "liquidity": liq.to_string(), "sqrt_min_price": smin.to_string(), "sqrt_max_price": smax.to_string(), "sqrt_price": s0.to_string(), "activation_type": 1, "collect_fee_mode": 1, "creator": s(&dk)}));
    r.account("desk_position", &env, &damm_position(&nft.pubkey()), json!({"pool": s(&pool), "nft_mint": s(&nft.pubkey()), "unlocked_liquidity": liq.to_string(), "vested_liquidity": "0", "permanent_locked_liquidity": "0"}));
    let ta = spl_token::state::Account::unpack(&env.raw(&desk_wx)[..165]).unwrap();
    r.account("desk_wx_ata", &env, &desk_wx, json!({"mint": s(&ta.mint), "owner": s(&ta.owner), "amount": ta.amount, "delegate": opt(ta.delegate.into()), "state": ta.state as u8, "is_native": Option::<u64>::from(ta.is_native), "delegated_amount": ta.delegated_amount, "close_authority": opt(ta.close_authority.into())}));
    let ta = spl_token::state::Account::unpack(&env.raw(&desk_wsol)[..165]).unwrap();
    r.account("desk_wsol_ata", &env, &desk_wsol, json!({"mint": s(&ta.mint), "owner": s(&ta.owner), "amount": ta.amount, "delegate": opt(ta.delegate.into()), "state": ta.state as u8, "is_native": Option::<u64>::from(ta.is_native), "delegated_amount": ta.delegated_amount, "close_authority": opt(ta.close_authority.into())}));

    // ---- 4. a DBC config quoted in wX, a coin under it
    let config_kp = kp(5);
    let config = config_kp.pubkey();
    let (sqrt_start, curve) = curve_for(T_WX);
    let cc = Instruction {
        program_id: DBC_ID,
        accounts: dbc::client::accounts::CreateConfig {
            config,
            fee_claimer: k,
            leftover_receiver: k,
            quote_mint: wx,
            payer,
            system_program: anchor_lang::system_program::ID,
            event_authority: event_authority(&DBC_ID),
            program: DBC_ID,
        }
        .to_account_metas(None),
        data: dbc::client::args::CreateConfig { config_parameters: wx_params(T_WX) }.data(),
    };
    env.send_ok("create_config", &[cc.clone()], &[&config_kp]);
    r.ix("dbc.create_config", &cc, json!({"config": s(&config), "fee_claimer": s(&k), "leftover_receiver": s(&k), "quote_mint": s(&wx), "payer": s(&payer),
        "t_wx": T_WX, "sqrt_start_price": sqrt_start.to_string(), "curve": curve.iter().map(|(a, b)| json!([a.to_string(), b.to_string()])).collect::<Vec<_>>()}));
    let a = env.svm.get_account(&config).unwrap();
    let cfg = dbcread::parse_config(&a.owner, &a.data).unwrap();
    r.account("dbc_config", &env, &config, json!({"quote_mint": s(&cfg.quote_mint), "fee_claimer": s(&cfg.fee_claimer), "leftover_receiver": s(&cfg.leftover_receiver),
        "collect_fee_mode": cfg.collect_fee_mode, "migration_option": cfg.migration_option, "activation_type": cfg.activation_type, "token_type": cfg.token_type,
        "partner_permanent_locked_liquidity_percentage": cfg.partner_permanent_locked_liquidity_percentage, "partner_liquidity_percentage": cfg.partner_liquidity_percentage,
        "creator_permanent_locked_liquidity_percentage": cfg.creator_permanent_locked_liquidity_percentage, "creator_liquidity_percentage": cfg.creator_liquidity_percentage,
        "migration_fee_option": cfg.migration_fee_option, "creator_trading_fee_percentage": cfg.creator_trading_fee_percentage, "migration_fee_percentage": cfg.migration_fee_percentage,
        "creator_migration_fee_percentage": cfg.creator_migration_fee_percentage, "migration_quote_threshold": cfg.migration_quote_threshold, "version": cfg.version,
        "fixed_token_supply_flag": cfg.fixed_token_supply_flag, "pre_migration_token_supply": cfg.pre_migration_token_supply, "post_migration_token_supply": cfg.post_migration_token_supply,
        "migrated_collect_fee_mode": cfg.migrated_collect_fee_mode, "migrated_compounding_fee_bps": cfg.migrated_compounding_fee_bps, "pool_creation_fee": cfg.pool_creation_fee,
        "partner_vesting_initialized": cfg.partner_vesting_initialized, "creator_vesting_initialized": cfg.creator_vesting_initialized,
        "sqrt_start_price": sqrt_start.to_string(), "token_decimal": 6, "token_update_authority": 1, "cliff_fee_numerator": FEE_CLIFF, "fee_periods": FEE_PERIODS, "fee_period_secs": FEE_PERIOD_SECS, "fee_reduction": FEE_REDUCTION,
        "curve": curve.iter().map(|(a, b)| json!([a.to_string(), b.to_string()])).collect::<Vec<_>>()}));

    let creator = kp(6);
    env.svm.airdrop(&creator.pubkey(), 10 * LAMPORTS).unwrap();
    let coin_kp = kp(7);
    let coin = coin_kp.pubkey();
    let dpool = dbc_pool_q(&config, &coin, &wx);
    let base_vault = dbc_vault(&coin, &dpool);
    let quote_vault = dbc_vault(&wx, &dpool);
    let launch = Instruction {
        program_id: DBC_ID,
        accounts: dbc::client::accounts::InitializeVirtualPoolWithSplToken {
            config,
            pool_authority: DBC_POOL_AUTHORITY,
            creator: creator.pubkey(),
            base_mint: coin,
            quote_mint: wx,
            pool: dpool,
            base_vault,
            quote_vault,
            mint_metadata: metadata_pda(&coin),
            metadata_program: MPL_ID,
            payer,
            token_quote_program: spl_token::ID,
            token_program: spl_token::ID,
            system_program: anchor_lang::system_program::ID,
            event_authority: event_authority(&DBC_ID),
            program: DBC_ID,
        }
        .to_account_metas(None),
        data: dbc::client::args::InitializeVirtualPoolWithSplToken {
            params: dbct::InitializePoolParameters { name: "Milady Coin".into(), symbol: "MILCOIN".into(), uri: "https://rook.example/c.json".into() },
        }
        .data(),
    };
    env.send_ok("launch", &[launch.clone()], &[&creator, &coin_kp]);
    r.ix("dbc.initialize_virtual_pool_with_spl_token", &launch, json!({"config": s(&config), "creator": s(&creator.pubkey()), "base_mint": s(&coin), "quote_mint": s(&wx), "payer": s(&payer),
        "name": "Milady Coin", "symbol": "MILCOIN", "uri": "https://rook.example/c.json"}));
    env.warp(700);

    let swap_metas = |payer_k: Pubkey, input: Pubkey, output: Pubkey| {
        dbc::client::accounts::Swap2 {
            pool_authority: DBC_POOL_AUTHORITY,
            config,
            pool: dpool,
            input_token_account: input,
            output_token_account: output,
            base_vault,
            quote_vault,
            base_mint: coin,
            quote_mint: wx,
            payer: payer_k,
            token_base_program: spl_token::ID,
            token_quote_program: spl_token::ID,
            referral_token_account: None,
            event_authority: event_authority(&DBC_ID),
            program: DBC_ID,
        }
        .to_account_metas(None)
    };

    // ---- 5. the site's own two-hop buy, pre-graduation (S2 §3.5): a fresh wallet, one legacy transaction
    let user = kp(16);
    env.svm.airdrop(&user.pubkey(), 3 * LAMPORTS).unwrap();
    let uk = user.pubkey();
    let u_wsol = get_associated_token_address(&uk, &NATIVE_MINT);
    let u_wx = get_associated_token_address(&uk, &wx);
    let u_coin = get_associated_token_address(&uk, &coin);
    let sol_in = LAMPORTS / 10;
    let wx_min = (sol_in as f64 / 18.61 * 0.97) as u64;
    let bundle = |coin_hop: Instruction| -> Vec<Instruction> {
        vec![
            ComputeBudgetInstruction::set_compute_unit_limit(400_000),
            ComputeBudgetInstruction::set_compute_unit_price(10_000),
            ata_ix::create_associated_token_account_idempotent(&uk, &uk, &NATIVE_MINT, &spl_token::ID),
            system_instruction::transfer(&uk, &u_wsol, sol_in),
            spl_token::instruction::sync_native(&spl_token::ID, &u_wsol).unwrap(),
            ata_ix::create_associated_token_account_idempotent(&uk, &uk, &wx, &spl_token::ID),
            ix_damm_swap(&wp, &uk, u_wsol, u_wx, sol_in, wx_min),
            ata_ix::create_associated_token_account_idempotent(&uk, &uk, &coin, &spl_token::ID),
            coin_hop,
            spl_token::instruction::close_account(&spl_token::ID, &u_wsol, &uk, &uk, &[]).unwrap(),
        ]
    };
    let hop2 = Instruction {
        program_id: DBC_ID,
        accounts: swap_metas(uk, u_wx, u_coin),
        data: dbc::client::args::Swap2 { params: dbct::SwapParameters2 { amount_0: wx_min, amount_1: 1, swap_mode: 0 } }.data(),
    };
    let ixs = bundle(hop2);
    send_as(&mut env, &user, &ixs);
    r.bundles.push(json!({"name": "site.two_hop_pre_graduation", "payer": s(&uk), "params": {"user": s(&uk), "wx_pool": s(&pool), "wx_mint": s(&wx), "coin_mint": s(&coin), "dbc_config": s(&config), "dbc_pool": s(&dpool),
        "sol_in": sol_in, "wx_min": wx_min, "coin_min": 1, "cu_limit": 400_000, "cu_price": 10_000},
        "instructions": ixs.iter().map(|i| jix("", i, Value::Null)).collect::<Vec<_>>()}));

    // ---- 6. buys on the curve: plain ATA create, MintTo, DBC swap (v1), swap2 partial fill
    let whale = kp(8);
    env.svm.airdrop(&whale.pubkey(), 5 * LAMPORTS).unwrap();
    let wk = whale.pubkey();
    let whale_wx = get_associated_token_address(&wk, &wx);
    let whale_coin = get_associated_token_address(&wk, &coin);
    let ac = ata_ix::create_associated_token_account(&payer, &wk, &wx, &spl_token::ID);
    let mt2 = spl_token::instruction::mint_to(&spl_token::ID, &wx, &whale_wx, &k, &[], 2 * T_WX * LAMPORTS).unwrap();
    let ac2 = ata_ix::create_associated_token_account_idempotent(&payer, &wk, &coin, &spl_token::ID);
    env.send_ok("whale funds", &[ac.clone(), mt2.clone(), ac2], &[&canister]);
    r.ix("ata.create", &ac, json!({"payer": s(&payer), "owner": s(&wk), "mint": s(&wx)}));
    r.ix("spl.mint_to", &mt2, json!({"mint": s(&wx), "dest": s(&whale_wx), "authority": s(&k), "amount": 2 * T_WX * LAMPORTS}));
    let sw1 = Instruction {
        program_id: DBC_ID,
        accounts: dbc::client::accounts::Swap {
            pool_authority: DBC_POOL_AUTHORITY,
            config,
            pool: dpool,
            input_token_account: whale_wx,
            output_token_account: whale_coin,
            base_vault,
            quote_vault,
            base_mint: coin,
            quote_mint: wx,
            payer: wk,
            token_base_program: spl_token::ID,
            token_quote_program: spl_token::ID,
            referral_token_account: None,
            event_authority: event_authority(&DBC_ID),
            program: DBC_ID,
        }
        .to_account_metas(None),
        data: dbc::client::args::Swap { params: dbct::SwapParameters { amount_in: LAMPORTS / 10, minimum_amount_out: 0 } }.data(),
    };
    env.send_ok("dbc swap", &[sw1.clone()], &[&whale]);
    r.ix("dbc.swap", &sw1, json!({"config": s(&config), "pool": s(&dpool), "base_mint": s(&coin), "quote_mint": s(&wx), "payer": s(&wk), "input": s(&whale_wx), "output": s(&whale_coin), "amount_in": LAMPORTS / 10, "minimum_amount_out": 0}));
    let sw2 = Instruction {
        program_id: DBC_ID,
        accounts: swap_metas(wk, whale_wx, whale_coin),
        data: dbc::client::args::Swap2 { params: dbct::SwapParameters2 { amount_0: 2 * T_WX * LAMPORTS, amount_1: 0, swap_mode: 1 } }.data(),
    };
    env.send_ok("dbc swap2", &[sw2.clone()], &[&whale]);
    r.ix("dbc.swap2", &sw2, json!({"config": s(&config), "pool": s(&dpool), "base_mint": s(&coin), "quote_mint": s(&wx), "payer": s(&wk), "input": s(&whale_wx), "output": s(&whale_coin), "amount_0": 2 * T_WX * LAMPORTS, "amount_1": 0, "swap_mode": 1}));
    let a = env.svm.get_account(&dpool).unwrap();
    let p = dbcread::parse_pool(&a.owner, &a.data).unwrap();
    r.account("dbc_pool_graduated", &env, &dpool, json!({"config": s(&p.config), "creator": s(&p.creator), "base_mint": s(&p.base_mint), "base_vault": s(&p.base_vault), "quote_vault": s(&p.quote_vault),
        "quote_reserve": p.quote_reserve, "activation_point": p.activation_point, "is_migrated": p.is_migrated, "migration_progress": p.migration_progress, "migration_fee_withdraw_status": p.migration_fee_withdraw_status}));

    // ---- 7. curve fees to K_fc (in wX)
    let fc_wx = get_associated_token_address(&k, &wx);
    let fc_coin = get_associated_token_address(&k, &coin);
    env.send_ok("fc atas", &[ata_ix::create_associated_token_account_idempotent(&payer, &k, &wx, &spl_token::ID), ata_ix::create_associated_token_account_idempotent(&payer, &k, &coin, &spl_token::ID)], &[]);
    let ctf = Instruction {
        program_id: DBC_ID,
        accounts: dbc::client::accounts::ClaimTradingFee {
            pool_authority: DBC_POOL_AUTHORITY,
            config,
            pool: dpool,
            token_a_account: fc_coin,
            token_b_account: fc_wx,
            base_vault,
            quote_vault,
            base_mint: coin,
            quote_mint: wx,
            fee_claimer: k,
            token_base_program: spl_token::ID,
            token_quote_program: spl_token::ID,
            event_authority: event_authority(&DBC_ID),
            program: DBC_ID,
        }
        .to_account_metas(None),
        data: dbc::client::args::ClaimTradingFee { max_amount_a: u64::MAX, max_amount_b: u64::MAX }.data(),
    };
    env.send_ok("claim_trading_fee", &[ctf.clone()], &[&canister]);
    r.ix("dbc.claim_trading_fee", &ctf, json!({"config": s(&config), "pool": s(&dpool), "base_mint": s(&coin), "quote_mint": s(&wx), "fee_claimer": s(&k), "token_a_account": s(&fc_coin), "token_b_account": s(&fc_wx), "max_amount_a": u64::MAX.to_string(), "max_amount_b": u64::MAX.to_string()}));
    assert!(env.token_amount(&fc_wx) > 0);

    // ---- 8. migration (permissionless)
    let mpool = damm_mig_pool(&coin, &wx);
    let (nft1, nft2, anyone) = (kp(9), kp(10), kp(11));
    env.svm.airdrop(&anyone.pubkey(), 2 * LAMPORTS).unwrap();
    let mut metas = dbc::client::accounts::MigrationDammV2 {
        virtual_pool: dpool,
        migration_metadata: anchor_lang::system_program::ID,
        config,
        pool_authority: DBC_POOL_AUTHORITY,
        pool: mpool,
        first_position_nft_mint: nft1.pubkey(),
        first_position_nft_account: damm_position_nft_account(&nft1.pubkey()),
        first_position: damm_position(&nft1.pubkey()),
        second_position_nft_mint: Some(nft2.pubkey()),
        second_position_nft_account: Some(damm_position_nft_account(&nft2.pubkey())),
        second_position: Some(damm_position(&nft2.pubkey())),
        damm_pool_authority: DAMM_V2_POOL_AUTHORITY,
        amm_program: DAMM_V2_ID,
        base_mint: coin,
        quote_mint: wx,
        token_a_vault: damm_vault(&coin, &mpool),
        token_b_vault: damm_vault(&wx, &mpool),
        base_vault,
        quote_vault,
        payer: anyone.pubkey(),
        token_base_program: spl_token::ID,
        token_quote_program: spl_token::ID,
        token_2022_program: TOKEN_2022_ID,
        damm_event_authority: event_authority(&DAMM_V2_ID),
        system_program: anchor_lang::system_program::ID,
    }
    .to_account_metas(None);
    metas.push(AccountMeta::new_readonly(DAMM_CONFIG_CUSTOMIZABLE, false));
    let mig = Instruction { program_id: DBC_ID, accounts: metas, data: dbc::client::args::MigrationDammV2 {}.data() };
    env.send_ok("migration", &[mig.clone()], &[&anyone, &nft1, &nft2]);
    r.ix("dbc.migration_damm_v2", &mig, json!({"config": s(&config), "virtual_pool": s(&dpool), "base_mint": s(&coin), "quote_mint": s(&wx), "payer": s(&anyone.pubkey()),
        "first_nft": s(&nft1.pubkey()), "second_nft": s(&nft2.pubkey()), "damm_config": s(&DAMM_CONFIG_CUSTOMIZABLE)}));
    let a = env.svm.get_account(&dpool).unwrap();
    let p = dbcread::parse_pool(&a.owner, &a.data).unwrap();
    r.account("dbc_pool_migrated", &env, &dpool, json!({"config": s(&p.config), "creator": s(&p.creator), "base_mint": s(&p.base_mint), "base_vault": s(&p.base_vault), "quote_vault": s(&p.quote_vault),
        "quote_reserve": p.quote_reserve, "activation_point": p.activation_point, "is_migrated": p.is_migrated, "migration_progress": p.migration_progress, "migration_fee_withdraw_status": p.migration_fee_withdraw_status}));
    let partner_nft = if env.token_owner(&damm_position_nft_account(&nft1.pubkey())) == k { nft1.pubkey() } else { nft2.pubkey() };
    let mp = Damm { pool: mpool, a: coin, b: wx };

    // ---- 9. migration fee into K_coin's ATA (+ memo), surplus, leftover, burn
    let coin_owner = kp(12).pubkey();
    let vault_wx = get_associated_token_address(&coin_owner, &wx);
    let av = ata_ix::create_associated_token_account_idempotent(&payer, &coin_owner, &wx, &spl_token::ID);
    let wmf = Instruction {
        program_id: DBC_ID,
        accounts: dbc::client::accounts::WithdrawMigrationFee {
            pool_authority: DBC_POOL_AUTHORITY,
            config,
            virtual_pool: dpool,
            token_quote_account: vault_wx,
            quote_vault,
            quote_mint: wx,
            sender: k,
            token_quote_program: spl_token::ID,
            event_authority: event_authority(&DBC_ID),
            program: DBC_ID,
        }
        .to_account_metas(None),
        data: dbc::client::args::WithdrawMigrationFee { flag: 0 }.data(),
    };
    let me2 = memo("rook:v1:0:back:1", &[]);
    env.send_ok("withdraw_migration_fee", &[av.clone(), wmf.clone(), me2.clone()], &[&canister]);
    r.ix("ata.create_idempotent", &av, json!({"payer": s(&payer), "owner": s(&coin_owner), "mint": s(&wx)}));
    r.ix("dbc.withdraw_migration_fee", &wmf, json!({"config": s(&config), "virtual_pool": s(&dpool), "quote_mint": s(&wx), "sender": s(&k), "token_quote_account": s(&vault_wx), "flag": 0}));
    r.ix("memo", &me2, json!({"text": "rook:v1:0:back:1", "signers": []}));
    assert_eq!(env.token_amount(&vault_wx), T_WX * LAMPORTS / 2);
    let sur = Instruction {
        program_id: DBC_ID,
        accounts: dbc::client::accounts::PartnerWithdrawSurplus {
            pool_authority: DBC_POOL_AUTHORITY,
            config,
            virtual_pool: dpool,
            token_quote_account: fc_wx,
            quote_vault,
            quote_mint: wx,
            fee_claimer: k,
            token_quote_program: spl_token::ID,
            event_authority: event_authority(&DBC_ID),
            program: DBC_ID,
        }
        .to_account_metas(None),
        data: dbc::client::args::PartnerWithdrawSurplus {}.data(),
    };
    env.send_ok("surplus", &[sur.clone()], &[&canister]);
    r.ix("dbc.partner_withdraw_surplus", &sur, json!({"config": s(&config), "virtual_pool": s(&dpool), "quote_mint": s(&wx), "fee_claimer": s(&k), "token_quote_account": s(&fc_wx)}));
    let wl = Instruction {
        program_id: DBC_ID,
        accounts: dbc::client::accounts::WithdrawLeftover {
            pool_authority: DBC_POOL_AUTHORITY,
            config,
            virtual_pool: dpool,
            token_base_account: fc_coin,
            base_vault,
            base_mint: coin,
            leftover_receiver: k,
            token_base_program: spl_token::ID,
            event_authority: event_authority(&DBC_ID),
            program: DBC_ID,
        }
        .to_account_metas(None),
        data: dbc::client::args::WithdrawLeftover {}.data(),
    };
    env.send_ok("leftover", &[wl.clone()], &[]);
    r.ix("dbc.withdraw_leftover", &wl, json!({"config": s(&config), "virtual_pool": s(&dpool), "base_mint": s(&coin), "leftover_receiver": s(&k)}));
    let left = env.token_amount(&fc_coin);
    assert!(left > 0);
    let bc = spl_token::instruction::burn_checked(&spl_token::ID, &fc_coin, &coin, &k, &[], left, 6).unwrap();
    env.send_ok("burn leftover", &[bc.clone()], &[&canister]);
    r.ix("spl.burn_checked", &bc, json!({"account": s(&fc_coin), "mint": s(&coin), "owner": s(&k), "amount": left, "decimals": 6}));

    // ---- 10. the site's two-hop buy, post-graduation
    let hop2 = ix_damm_swap(&mp, &uk, u_wx, u_coin, wx_min, 1);
    let ixs = bundle(hop2);
    send_as(&mut env, &user, &ixs);
    r.bundles.push(json!({"name": "site.two_hop_post_graduation", "payer": s(&uk), "params": {"user": s(&uk), "wx_pool": s(&pool), "wx_mint": s(&wx), "coin_mint": s(&coin), "coin_pool": s(&mpool),
        "sol_in": sol_in, "wx_min": wx_min, "coin_min": 1, "cu_limit": 400_000, "cu_price": 10_000},
        "instructions": ixs.iter().map(|i| jix("", i, Value::Null)).collect::<Vec<_>>()}));

    // trade on the graduated pool, then the partner LP fees in wX
    let trader = kp(17);
    env.svm.airdrop(&trader.pubkey(), 30 * LAMPORTS).unwrap();
    let tk = trader.pubkey();
    let t_wx = get_associated_token_address(&tk, &wx);
    let t_coin = get_associated_token_address(&tk, &coin);
    env.send_ok("trader", &[ata_ix::create_associated_token_account_idempotent(&payer, &tk, &wx, &spl_token::ID), ata_ix::create_associated_token_account_idempotent(&payer, &tk, &coin, &spl_token::ID),
        spl_token::instruction::mint_to_checked(&spl_token::ID, &wx, &t_wx, &k, &[], LAMPORTS, 9).unwrap()], &[&canister]);
    let ds = ix_damm_swap(&mp, &tk, t_wx, t_coin, LAMPORTS / 2, 0);
    env.send_ok("damm swap", &[ds.clone()], &[&trader]);
    r.ix("damm.swap", &ds, json!({"pool": s(&mpool), "token_a_mint": s(&coin), "token_b_mint": s(&wx), "payer": s(&tk), "input": s(&t_wx), "output": s(&t_coin), "amount_in": LAMPORTS / 2, "minimum_amount_out": 0}));
    let got = env.token_amount(&t_coin);
    let ds2 = ix_damm_swap2(&mp, &tk, t_coin, t_wx, got / 2, 0, 0);
    env.send_ok("damm swap2", &[ds2.clone()], &[&trader]);
    r.ix("damm.swap2", &ds2, json!({"pool": s(&mpool), "token_a_mint": s(&coin), "token_b_mint": s(&wx), "payer": s(&tk), "input": s(&t_coin), "output": s(&t_wx), "amount_0": got / 2, "amount_1": 0, "swap_mode": 0}));
    let pc = ix_damm_claim(&mp, &partner_nft, &k, fc_coin, fc_wx);
    env.send_ok("partner claim", &[pc.clone()], &[&canister]);
    r.ix("damm.claim_position_fee", &pc, json!({"pool": s(&mpool), "token_a_mint": s(&coin), "token_b_mint": s(&wx), "nft_mint": s(&partner_nft), "owner": s(&k), "token_a_account": s(&fc_coin), "token_b_account": s(&fc_wx)}));
    r.account("partner_position", &env, &damm_position(&partner_nft), json!({"pool": s(&mpool), "nft_mint": s(&partner_nft), "unlocked_liquidity": "0", "vested_liquidity": "0"}));
    r.account("migrated_pool", &env, &mpool, json!({"token_a_mint": s(&coin), "token_b_mint": s(&wx), "token_a_vault": s(&mp.va()), "token_b_vault": s(&mp.vb()), "collect_fee_mode": 1}));

    // ---- 11. the desk's position on the wX/SOL pool: trades, fees, add, remove, close, re-open
    let t_wsol = get_associated_token_address(&tk, &NATIVE_MINT);
    env.send_ok("trader wsol", &[ata_ix::create_associated_token_account_idempotent(&payer, &tk, &NATIVE_MINT, &spl_token::ID), system_instruction::transfer(&tk, &t_wsol, 2 * LAMPORTS),
        spl_token::instruction::sync_native(&spl_token::ID, &t_wsol).unwrap()], &[&trader]);
    let w0 = env.token_amount(&t_wx);
    let ds3 = ix_damm_swap(&wp, &tk, t_wsol, t_wx, LAMPORTS / 10, 1);
    env.send_ok("buy wX", &[ds3.clone()], &[&trader]);
    r.ix("damm.swap", &ds3, json!({"pool": s(&pool), "token_a_mint": s(&wx), "token_b_mint": s(&NATIVE_MINT), "payer": s(&tk), "input": s(&t_wsol), "output": s(&t_wx), "amount_in": LAMPORTS / 10, "minimum_amount_out": 1}));
    let bought = env.token_amount(&t_wx) - w0;
    let ds4 = ix_damm_swap2(&wp, &tk, t_wx, t_wsol, bought, 1, 0);
    env.send_ok("sell wX", &[ds4.clone()], &[&trader]);
    r.ix("damm.swap2", &ds4, json!({"pool": s(&pool), "token_a_mint": s(&wx), "token_b_mint": s(&NATIVE_MINT), "payer": s(&tk), "input": s(&t_wx), "output": s(&t_wsol), "amount_0": bought, "amount_1": 1, "swap_mode": 0}));
    let dc = ix_damm_claim(&wp, &nft.pubkey(), &dk, desk_wx, desk_wsol);
    env.send_ok("desk claim", &[dc.clone()], &[&desk]);
    r.ix("damm.claim_position_fee", &dc, json!({"pool": s(&pool), "token_a_mint": s(&wx), "token_b_mint": s(&NATIVE_MINT), "nft_mint": s(&nft.pubkey()), "owner": s(&dk), "token_a_account": s(&desk_wx), "token_b_account": s(&desk_wsol)}));
    // add liquidity (fresh wX from the module + wrapped SOL)
    let add_wx = seed_wx / 4;
    let add_sol = seed_sol / 4;
    env.send_ok("mint + wrap", &[spl_token::instruction::mint_to_checked(&spl_token::ID, &wx, &desk_wx, &k, &[], add_wx, 9).unwrap(), system_instruction::transfer(&dk, &desk_wsol, add_sol),
        spl_token::instruction::sync_native(&spl_token::ID, &desk_wsol).unwrap()], &[&canister, &desk]);
    let dl = liquidity_for(add_wx, add_sol, s0, smin, smax) / 2;
    let ad = ix_damm_add(&wp, &nft.pubkey(), &dk, desk_wx, desk_wsol, dl, u64::MAX, u64::MAX);
    env.send_ok("add", &[ad.clone()], &[&desk]);
    r.ix("damm.add_liquidity", &ad, json!({"pool": s(&pool), "token_a_mint": s(&wx), "token_b_mint": s(&NATIVE_MINT), "nft_mint": s(&nft.pubkey()), "owner": s(&dk), "token_a_account": s(&desk_wx), "token_b_account": s(&desk_wsol),
        "liquidity_delta": dl.to_string(), "token_a_amount_threshold": u64::MAX.to_string(), "token_b_amount_threshold": u64::MAX.to_string()}));
    let rm = Instruction {
        program_id: DAMM_V2_ID,
        accounts: remove_accounts(&wp, &nft.pubkey(), &dk, desk_wx, desk_wsol),
        data: cp_amm::client::args::RemoveLiquidity { params: cp_amm::types::RemoveLiquidityParameters { liquidity_delta: liq / 4, token_a_amount_threshold: 1, token_b_amount_threshold: 2 } }.data(),
    };
    env.send_ok("remove", &[rm.clone()], &[&desk]);
    r.ix("damm.remove_liquidity", &rm, json!({"pool": s(&pool), "token_a_mint": s(&wx), "token_b_mint": s(&NATIVE_MINT), "nft_mint": s(&nft.pubkey()), "owner": s(&dk), "token_a_account": s(&desk_wx), "token_b_account": s(&desk_wsol),
        "liquidity_delta": (liq / 4).to_string(), "token_a_amount_threshold": "1", "token_b_amount_threshold": "2"}));
    let ra = Instruction {
        program_id: DAMM_V2_ID,
        accounts: remove_accounts(&wp, &nft.pubkey(), &dk, desk_wx, desk_wsol),
        data: cp_amm::client::args::RemoveAllLiquidity { token_a_amount_threshold: 0, token_b_amount_threshold: 0 }.data(),
    };
    env.send_ok("remove all", &[ra.clone()], &[&desk]);
    r.ix("damm.remove_all_liquidity", &ra, json!({"pool": s(&pool), "token_a_mint": s(&wx), "token_b_mint": s(&NATIVE_MINT), "nft_mint": s(&nft.pubkey()), "owner": s(&dk), "token_a_account": s(&desk_wx), "token_b_account": s(&desk_wsol),
        "token_a_amount_threshold": "0", "token_b_amount_threshold": "0"}));
    // burn the recovered wX at the module (plain Burn), close the position (rent back to the desk)
    let recovered = env.token_amount(&desk_wx);
    let bu = spl_token::instruction::burn(&spl_token::ID, &desk_wx, &wx, &dk, &[], recovered / 2).unwrap();
    env.send_ok("burn", &[bu.clone()], &[&desk]);
    r.ix("spl.burn", &bu, json!({"account": s(&desk_wx), "mint": s(&wx), "owner": s(&dk), "amount": recovered / 2}));
    let cl = Instruction {
        program_id: DAMM_V2_ID,
        accounts: cp_amm::client::accounts::ClosePosition {
            position_nft_mint: nft.pubkey(),
            position_nft_account: damm_position_nft_account(&nft.pubkey()),
            pool,
            position: damm_position(&nft.pubkey()),
            pool_authority: DAMM_V2_POOL_AUTHORITY,
            rent_receiver: dk,
            owner: dk,
            token_program: TOKEN_2022_ID,
            event_authority: event_authority(&DAMM_V2_ID),
            program: DAMM_V2_ID,
        }
        .to_account_metas(None),
        data: cp_amm::client::args::ClosePosition {}.data(),
    };
    env.send_ok("close", &[cl.clone()], &[&desk]);
    r.ix("damm.close_position", &cl, json!({"pool": s(&pool), "nft_mint": s(&nft.pubkey()), "owner": s(&dk), "rent_receiver": s(&dk)}));
    // re-open: a new position (its NFT mint signs: the throwaway key of §1.1) + add_liquidity
    let nft_b = kp(15);
    let cp = Instruction {
        program_id: DAMM_V2_ID,
        accounts: cp_amm::client::accounts::CreatePosition {
            owner: dk,
            position_nft_mint: nft_b.pubkey(),
            position_nft_account: damm_position_nft_account(&nft_b.pubkey()),
            pool,
            position: damm_position(&nft_b.pubkey()),
            pool_authority: DAMM_V2_POOL_AUTHORITY,
            payer: dk,
            token_program: TOKEN_2022_ID,
            system_program: anchor_lang::system_program::ID,
            event_authority: event_authority(&DAMM_V2_ID),
            program: DAMM_V2_ID,
        }
        .to_account_metas(None),
        data: cp_amm::client::args::CreatePosition {}.data(),
    };
    let ad2 = ix_damm_add(&wp, &nft_b.pubkey(), &dk, desk_wx, desk_wsol, liq / 8, u64::MAX, u64::MAX);
    env.send_ok("re-open", &[cp.clone(), ad2], &[&desk, &nft_b]);
    r.ix("damm.create_position", &cp, json!({"pool": s(&pool), "nft_mint": s(&nft_b.pubkey()), "owner": s(&dk), "payer": s(&dk)}));

    // ---- (IDL only, not sent) a re-centred pool on a DAMM v2 dynamic config whose pool_creator_authority is K_desk: the range is
    // the POOL's in DAMM v2, so moving it means a new pool; dynamic configs are created by Meteora's operator, none exists here.
    let dyn_config = kp(31).pubkey();
    let nft_c = kp(32).pubkey();
    let (lo2, hi2) = ((s0 as f64 * 1.2 / 1.1) as u128, (s0 as f64 * 1.2 * 1.1) as u128);
    let dyn_pool = pda(&[b"pool", dyn_config.as_ref(), ordered(&wx, &NATIVE_MINT).0.as_ref(), ordered(&wx, &NATIVE_MINT).1.as_ref()], &DAMM_V2_ID);
    let dparams = cp_amm::types::InitializeCustomizablePoolParameters {
        pool_fees: cp_amm::types::PoolFeeParameters { base_fee: base_fee(5_000_000), compounding_fee_bps: 0, padding: 0, dynamic_fee: None },
        sqrt_min_price: lo2,
        sqrt_max_price: hi2,
        has_alpha_vault: false,
        liquidity: liq / 3,
        sqrt_price: (s0 as f64 * 1.2) as u128,
        activation_type: 1,
        collect_fee_mode: 1,
        activation_point: None,
    };
    let dinit = Instruction {
        program_id: DAMM_V2_ID,
        accounts: cp_amm::client::accounts::InitializePoolWithDynamicConfig {
            creator: dk,
            position_nft_mint: nft_c,
            position_nft_account: damm_position_nft_account(&nft_c),
            payer: dk,
            pool_creator_authority: dk,
            config: dyn_config,
            pool_authority: DAMM_V2_POOL_AUTHORITY,
            pool: dyn_pool,
            position: damm_position(&nft_c),
            token_a_mint: wx,
            token_b_mint: NATIVE_MINT,
            token_a_vault: damm_vault(&wx, &dyn_pool),
            token_b_vault: damm_vault(&NATIVE_MINT, &dyn_pool),
            payer_token_a: desk_wx,
            payer_token_b: desk_wsol,
            token_a_program: spl_token::ID,
            token_b_program: spl_token::ID,
            token_2022_program: TOKEN_2022_ID,
            system_program: anchor_lang::system_program::ID,
            event_authority: event_authority(&DAMM_V2_ID),
            program: DAMM_V2_ID,
        }
        .to_account_metas(None),
        data: cp_amm::client::args::InitializePoolWithDynamicConfig { params: dparams }.data(),
    };
    r.idl_only.push(jix("damm.initialize_pool_with_dynamic_config", &dinit, json!({
        "creator": s(&dk), "payer": s(&dk), "pool_creator_authority": s(&dk), "config": s(&dyn_config), "nft_mint": s(&nft_c), "token_a_mint": s(&wx), "token_b_mint": s(&NATIVE_MINT),
        "payer_token_a": s(&desk_wx), "payer_token_b": s(&desk_wsol), "fee_numerator": 5_000_000u64, "sqrt_min_price": lo2.to_string(), "sqrt_max_price": hi2.to_string(),
        "liquidity": (liq / 3).to_string(), "sqrt_price": ((s0 as f64 * 1.2) as u128).to_string(), "activation_type": 1, "collect_fee_mode": 1, "pool": s(&dyn_pool)
    })));

    // ---- 12. moving wX: Transfer, TransferChecked; closing an emptied account
    let tr1 = spl_token::instruction::transfer(&spl_token::ID, &t_wx, &whale_wx, &tk, &[], 1_000).unwrap();
    let tr2 = spl_token::instruction::transfer_checked(&spl_token::ID, &t_wx, &wx, &whale_wx, &tk, &[], 2_000, 9).unwrap();
    env.send_ok("transfers", &[tr1.clone(), tr2.clone()], &[&trader]);
    r.ix("spl.transfer", &tr1, json!({"source": s(&t_wx), "dest": s(&whale_wx), "owner": s(&tk), "amount": 1_000}));
    r.ix("spl.transfer_checked", &tr2, json!({"source": s(&t_wx), "mint": s(&wx), "dest": s(&whale_wx), "owner": s(&tk), "amount": 2_000, "decimals": 9}));
    let ca = spl_token::instruction::close_account(&spl_token::ID, &t_wsol, &tk, &tk, &[]).unwrap();
    env.send_ok("close wsol", &[ca.clone()], &[&trader]);
    r.ix("spl.close_account", &ca, json!({"account": s(&t_wsol), "dest": s(&tk), "owner": s(&tk)}));

    let keys = json!({
        "k_main": s(&payer), "hot": s(&hot.pubkey()), "wx_mint": s(&wx), "k_coll": s(&k), "k_fc": s(&k), "k_desk": s(&dk), "k_coin": s(&coin_owner),
        "dbc_config": s(&config), "coin_mint": s(&coin), "dbc_pool": s(&dpool), "migrated_pool": s(&mpool), "wx_sol_pool": s(&pool),
        "desk_nft": s(&nft.pubkey()), "desk_nft_2": s(&nft_b.pubkey()), "partner_nft": s(&partner_nft),
        "dbc_pool_authority": s(&DBC_POOL_AUTHORITY), "damm_pool_authority": s(&DAMM_V2_POOL_AUTHORITY), "damm_config_customizable": s(&DAMM_CONFIG_CUSTOMIZABLE),
        "dbc_event_authority": s(&event_authority(&DBC_ID)), "damm_event_authority": s(&event_authority(&DAMM_V2_ID)), "wx_metadata": s(&metadata_pda(&wx)),
    });
    let out = json!({
        "about": "W2 fixtures: every instruction landed in LiteSVM 0.10 against mainnet DBC 0.2.1, DAMM v2 0.2.4 and Metaplex Token Metadata (solana/tests/solix2_fixtures.rs). Built with spl-token, spl-associated-token-account and the Anchor clients declare_program! generates from the official IDLs.",
        "keys": keys,
        "instructions": r.ixs,
        "idl_only": r.idl_only,
        "bundles": r.bundles,
        "accounts": r.accounts,
    });
    let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../autobuyer/canister-rs/tests/fixtures/solix2/flow.json");
    std::fs::create_dir_all(path.parent().unwrap()).unwrap();
    std::fs::write(&path, serde_json::to_string_pretty(&out).unwrap()).unwrap();
    println!("wrote {} instructions, {} bundles, {} accounts to {}", out["instructions"].as_array().unwrap().len(), out["bundles"].as_array().unwrap().len(), out["accounts"].as_array().unwrap().len(), path.display());
}

fn send_as(env: &mut Env, user: &Keypair, ixs: &[Instruction]) {
    let msg = solana_message::Message::new_with_blockhash(ixs, Some(&user.pubkey()), &env.svm.latest_blockhash());
    let tx = solana_transaction::versioned::VersionedTransaction::try_new(solana_message::VersionedMessage::Legacy(msg), &[user]).unwrap();
    let r = env.svm.send_transaction(tx);
    env.svm.expire_blockhash();
    r.unwrap_or_else(|e| panic!("bundle failed: {:?}\n{}", e.err, e.meta.logs.join("\n")));
}
